fn main() {
    generate_registry_history();
    #[cfg(feature = "desktop")]
    {
        // tauri-build does not remove obsolete autogenerated command permissions.
        // These files are build output owned by this prototype; regenerate for each feature profile.
        let generated = std::path::Path::new("permissions/autogenerated");
        if generated.exists() {
            std::fs::remove_dir_all(generated).expect("Reset generated profile command ACL");
        }
        #[cfg(feature = "acceptance")]
        let commands: &'static [&'static str] = &[
            "product_lifecycle_request",
            "workspace_request",
            "product_store_request",
            "mcp_service_request",
            "product_binary_request",
            "product_binary_read",
            "product_binary_write",
            "desktop_media_request",
            "skill_import_directory",
            "product_media_preview",
            "product_media_release",
            "workspace_cancel",
            "authorize_http_origin",
            "product_save_begin",
            "product_save_chunk",
            "product_save_finish",
            "product_save_cancel",
            "product_print_storyboard",
            "product_open_external",
            "acceptance_request",
        ];
        #[cfg(not(feature = "acceptance"))]
        let commands: &'static [&'static str] = &[
            "product_lifecycle_request",
            "workspace_request",
            "product_store_request",
            "mcp_service_request",
            "product_binary_request",
            "product_binary_read",
            "product_binary_write",
            "desktop_media_request",
            "skill_import_directory",
            "product_media_preview",
            "product_media_release",
            "workspace_cancel",
            "authorize_http_origin",
            "product_save_begin",
            "product_save_chunk",
            "product_save_finish",
            "product_save_cancel",
            "product_print_storyboard",
            "product_open_external",
        ];
        tauri_build::try_build(
            tauri_build::Attributes::new()
                .app_manifest(tauri_build::AppManifest::new().commands(commands)),
        )
        .expect("Build isolated command ACL");
    }
}

fn generate_registry_history() {
    let history = std::path::PathBuf::from(
        std::env::var_os("CARGO_MANIFEST_DIR").expect("Cargo manifest directory"),
    )
    .join("src/full_product_store/registry-history");
    println!("cargo:rerun-if-changed={}", history.display());
    let mut snapshots = std::fs::read_dir(&history)
        .expect("Read registry history")
        .map(|entry| entry.expect("Read registry history entry").path())
        .filter(|path| {
            path.extension()
                .is_some_and(|extension| extension == "json")
                && path.file_name().is_some_and(|name| name != "catalog.json")
        })
        .collect::<Vec<_>>();
    snapshots.sort();
    let mut generated = String::from("pub(super) const SNAPSHOTS: &[(&str, &str)] = &[\n");
    for path in snapshots {
        let name = path
            .file_name()
            .and_then(|name| name.to_str())
            .expect("UTF-8 registry snapshot filename");
        // Rust debug string literals preserve spaces, quotes and Windows path separators.
        generated.push_str(&format!("    ({name:?}, include_str!({path:?})),\n"));
    }
    generated.push_str("];\n");
    let output = std::path::PathBuf::from(
        std::env::var_os("OUT_DIR").expect("Cargo build output directory"),
    );
    std::fs::write(output.join("registry_history.rs"), generated)
        .expect("Write compiled registry history");
}
